pub(crate) fn thai_province(lat: f64, lon: f64) -> u8 {
    let row = ((PROVINCE_NORTH - lat) / PROVINCE_STEP).floor();
    let column = ((lon - PROVINCE_WEST) / PROVINCE_STEP).floor();
    if !(0.0..(PROVINCE_ROW_STARTS.len() - 1) as f64).contains(&row) || column < 0.0 {
        return 0;
    }
    let row = row as usize;
    let runs = &PROVINCE_RUNS
        [usize::from(PROVINCE_ROW_STARTS[row])..usize::from(PROVINCE_ROW_STARTS[row + 1])];
    let column = column as usize;
    let index = runs.partition_point(|&(end, _)| usize::from(end) <= column);
    runs.get(index).map_or(0, |&(_, province)| province)
}

/// The department's traffic of a Thai row: its ref's first number ("1", "3256;4", "AH2;4") as a
/// highway the department counts in the province of the row's middle.
pub(crate) fn thai_highway(
    reference: &str,
    lat: f64,
    lon: f64,
) -> Option<&'static (u16, u8, f64, [f64; 4])> {
    let number: u16 = reference
        .split(';')
        .map(str::trim)
        .find(|part| (1..=4).contains(&part.len()) && part.bytes().all(|b| b.is_ascii_digit()))?
        .parse()
        .ok()?;
    let province = thai_province(lat, lon);
    THAI_HIGHWAYS
        .binary_search_by_key(&(number, province), |row| (row.0, row.1))
        .ok()
        .map(|index| &THAI_HIGHWAYS[index])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn highways_are_found_by_number_and_province_and_their_shares_add_up() {
        assert!(
            THAI_HIGHWAYS
                .windows(2)
                .all(|w| (w[0].0, w[0].1) < (w[1].0, w[1].1))
        );
        for &(number, province, mean, shares) in THAI_HIGHWAYS.iter() {
            assert!(mean > 0.0 && province > 0, "{number}");
            assert!((shares.iter().sum::<f64>() - 1.0).abs() < 0.003, "{number}");
        }
        // Bangkok, Koh Samui (Surat Thani), Chiang Mai, the open Gulf, inland Laos.
        assert_eq!(thai_province(13.75, 100.50), 10);
        assert_eq!(thai_province(9.47, 99.95), 84);
        assert_eq!(thai_province(18.79, 98.98), 50);
        assert_eq!(thai_province(11.0, 101.5), 0);
        assert_eq!(thai_province(19.0, 102.5), 0);
        // Koh Samui's ring road: a third of its traffic on motorcycles.
        let samui = thai_highway("4169", 9.47, 99.95).unwrap();
        assert!(samui.3[3] > 0.3);
        // Highway 1 in Pathum Thani and in Lopburi; in Bangkok the department lists sections
        // that do not cover the OSM rows, and Lat Phrao's "336" is not the department's 336.
        assert!(thai_highway("1", 14.03, 100.62).unwrap().2 > 100_000.0);
        assert!(thai_highway("1", 14.80, 100.65).unwrap().2 < 15_000.0);
        assert!(thai_highway("1", 13.85, 100.56).is_none());
        assert!(thai_highway("336", 13.79, 100.59).is_none());
        assert_eq!(thai_highway("AH2;4", 13.08, 99.95).unwrap().0, 4);
        assert!(thai_highway("Sukhumvit", 13.6, 100.6).is_none());
        // Motorway 7 carries no motorcycles.
        assert_eq!(thai_highway("7", 13.38, 101.0).unwrap().3[3], 0.0);
    }
}
